    isbn_list = isbn.split('-')
    if len(isbn_list) != 4:
        return "Wrong format"

    isbn_sum = 0
    for i in range(12):
        isbn_sum += (i+1) * int(isbn_list[i])

    isbn_checksum = str(isbn_sum % 11)
    if isbn_checksum == '10':
        isbn_checksum = 'X'

    if isbn_checksum == isbn_list[3]:
        return "Right"
